export async function assertWebReuseNotExcluded(root,path,digest){let exclusions;try{exclusions=JSON.parse(await readFile(join(root,'integration','candidate-exclusions.json')));}catch(e){if(e.code==='ENOENT')return;throw e;}if(exclusions.schema!=='coach-textbook-candidate-exclusions/1')throw Error('web_candidate_exclusions_schema');if(exclusions.entries.some(e=>resolve(root,e.candidatePath)===resolve(root,path)&&e.candidateSha256===digest))throw Error('web_reuse_parent_explicitly_excluded');}
