 const parentBytes=await readFile(bound(root,d.parentCandidate.path));if(sha(parentBytes)!==d.parentCandidate.sha256)throw Error('web_verified_asset_parent_changed');const parent=JSON.parse(parentBytes),gate=await verifyAuditForWebCandidate(root,d.parentCandidate.path);
 if(gate.auditSha256!==d.parentAudit.sha256||gate.status!==d.parentAudit.status||gate.inputAdjudication?.sha256!==d.inputAdjudication?.sha256||gate.inputAdjudication?.originalCall.callId!==d.independentCallId)throw Error('web_verified_asset_parent_review_changed');
 const dictionaryBytes=await readFile(bound(root,d.sourceDictionary.path));if(sha(dictionaryBytes)!==d.sourceDictionary.sha256||!same(d.sourceDictionary,parent.provenance.dictionary)||!same(d.acceptedAssets,JSON.parse(dictionaryBytes).acceptedAssets))throw Error('web_verified_assets_exceed_parent_dictionary');
