  const parent=JSON.parse(parentBytes),original=parent.figures.find(f=>f.figureId===p.figureId),asset=figure.sourceAssetBindings[0],proof=map.images.find(x=>x.assetId===asset.assetId);
  if(!original||!same(figure.transcription,original.transcription)||!same(figure.unknowns,original.unknowns)||figure.kind!==original.kind||figure.caption!==original.caption)throw Error('web_reuse_transcription_changed');
  if(!proof?.reusePermitted||proof.assetSha256!==asset.sha256||!same(proof.pixelSignature,p.pixelSignature)||!proof.exactMatches.some(x=>x.candidatePath===p.candidatePath&&x.candidateSha256===p.candidateSha256&&x.sourceBlockId===p.sourceImageBlockId&&x.figures.some(f=>f.figureId===p.figureId)))throw Error('web_reuse_map_figure_binding');
  const originalPageMeta=JSON.parse(await readFile(join(processingRoot,'source-inventory.json'))).sources.find(s=>s.sourceId===parent.source.sourceId).pages.find(p=>p.page===parent.source.page);
  const page=JSON.parse(await readFile(bound(processingRoot,originalPageMeta.pageData))),image=page.blocks.find(b=>b.id===p.sourceImageBlockId);
  if(!image||!original.sourceImageBlockIds.includes(image.id)||p.sourceImagePath!==`assets/${image.imageSha256}.png`)throw Error('web_reuse_source_image_not_in_parent');
  const originalBytes=await readFile(bound(processingRoot,p.sourceImagePath));if(sha(originalBytes)!==image.imageSha256)throw Error('web_reuse_original_asset_changed');
  pairs.push({web:bound(processingRoot,asset.path),pdf:bound(processingRoot,p.sourceImagePath),expected:p.pixelSignature});
  evidence.push({figureId:figure.figureId,parentCandidate:{path:p.candidatePath,sha256:p.candidateSha256},parentFigureId:p.figureId,parentAudit:{path:gate.auditPath,sha256:sha(await readFile(gate.auditPath)),status:gate.status},pixelSignature:p.pixelSignature});
