 const pixels=await runPython(['-c',`import sys,json,hashlib\nfrom PIL import Image\nrows=json.load(sys.stdin)\nfor row in rows:\n a=Image.open(row['web']);b=Image.open(row['pdf'])\n assert getattr(a,'n_frames',1)==1 and getattr(b,'n_frames',1)==1,'animated_asset_not_exact_single_frame_reuse'\n a=a.convert('RGBA');b=b.convert('RGBA')\n signature=[list(a.size),hashlib.sha256(a.tobytes()).hexdigest()]\n assert a.size==b.size and a.tobytes()==b.tobytes() and signature==row['expected'],'independent_pixel_mismatch'\nprint(json.dumps({'passed':True,'pairs':len(rows),'method':'independent decoded RGBA dimensions and every pixel byte'}))`],JSON.stringify(pairs));
 if(source.language!=='zh-CN'||(!allowProductionModel&&(candidate.provenance.model!==null||candidate.provenance.reasoningEffort!==null||candidate.provenance.modelCalls!==0||candidate.provenance.attempts?.length!==0||candidate.provenance.usage!==null)))throw Error('web_exact_reuse_model_claim');
